For $K\in D^b_{\mathrm{ctf}}(X_{\mathrm{pro}\acute{e}t},A)$ with the stated Weil structure and every $m\geq1$, one has in $A$:

$$
\operatorname{tr}_{A}
\bigl(\operatorname{Frob}_{X,K}^m\mid R\Gamma_c(X_{\mathrm{pro}\acute{e}t},K)\bigr)
=\sum_{y\in X_0(\mathbf F_{q^m})}
\operatorname{tr}_{A}
\bigl(\operatorname{Frob}_{y,m}\mid K_{\bar y}\bigr).
\tag{12.3}
$$

For $K\in D^b_{\mathrm{ctf}}(X_{\mathrm{pro}\acute{e}t},\mathcal O_E)$ with the stated Weil structure and every $m\geq1$, one has in $\mathcal O_E$:

$$
\operatorname{tr}_{\mathcal O_E}
\bigl(\operatorname{Frob}_{X,K}^m\mid R\Gamma_c(X_{\mathrm{pro}\acute{e}t},K)\bigr)
=\sum_{y\in X_0(\mathbf F_{q^m})}
\operatorname{tr}_{\mathcal O_E}
\bigl(\operatorname{Frob}_{y,m}\mid K_{\bar y}\bigr).
$$

For $K\in D^b_{\mathrm{ctf}}(X_{\mathrm{pro}\acute{e}t},E)$ with the stated Weil structure and every $m\geq1$, one has in $E$:

$$
\operatorname{tr}_{E}
\bigl(\operatorname{Frob}_{X,K}^m\mid R\Gamma_c(X_{\mathrm{pro}\acute{e}t},K)\bigr)
=\sum_{y\in X_0(\mathbf F_{q^m})}
\operatorname{tr}_{E}
\bigl(\operatorname{Frob}_{y,m}\mid K_{\bar y}\bigr).
$$

For $K\in D^b_{\mathrm{ctf}}(X_{\mathrm{pro}\acute{e}t},\overline{\mathbf Q}_\ell)$ with the stated Weil structure and every $m\geq1$, one has in $\overline{\mathbf Q}_\ell$:

$$
\operatorname{tr}_{\overline{\mathbf Q}_\ell}
\bigl(\operatorname{Frob}_{X,K}^m\mid R\Gamma_c(X_{\mathrm{pro}\acute{e}t},K)\bigr)
=\sum_{y\in X_0(\mathbf F_{q^m})}
\operatorname{tr}_{\overline{\mathbf Q}_\ell}
\bigl(\operatorname{Frob}_{y,m}\mid K_{\bar y}\bigr).
$$

